![](C:\Users\HP\Desktop\Screenshots\屏幕截图 2025-11-07 172452.png) 连蚁剑 ![](C:\Users\HP\Desktop\Screenshots\屏幕截图 2025-11-07 172552.png) 连上蚁剑，发现一个flag文件（空的），一个readflag文件 ![](C:\Users\HP\Desktop\Screenshots\屏幕截图 2025-11-07 172703.png) 这里需要绕过这个disable_functions，并执行命令。 蚁剑有一个绕过disable_functions的插件，正好有PHP7的UAF ![](C:\Users\HP\Desktop\Screenshots\屏幕截图 2025-11-07 172951.png) 运行得到终端，运行&#x2F;readflag获得Flag: flag{0e52c31d-44f6-4e1d-b91f-600e08846d48} 方法二：[极客大挑战 2019]RCE ME（取反、异或绕过正则表达式、bypass disable_function）-CSDN博客 [De1CTF 2019]SSRF Me题目类型：代码审计hint:flag is in .&#x2F;flag.txt #! /usr/bin/env python# #encoding=utf-8from flask import Flaskfrom flask import requestimport socketimport hashlibimport urllibimport sysimport osimport jsonreload(sys)sys.setdefaultencoding(&#x27;latin1&#x27;) app = Flask(__name__) secert_key = os.urandom(16) class Task: def __init__(self, action, param, sign, ip): #是一个简单的赋值函数 self.action = action self.param = param self.sign = sign self.sandbox = md5(ip) if(not os.path.exists(self.sandbox)): #如果没有该文件夹，则创立一个文件夹 os.mkdir(self.sandbox) def Exec(self): result = &#123;&#125; result[&#x27;code&#x27;] = 500 if (self.checkSign()): if &quot;scan&quot; in self.action: tmpfile = open(&quot;./%s/result.txt&quot; % self.sandbox, &#x27;w&#x27;) #注意w，可以对result.txt文件进行修改 resp = scan(self.param) if (resp == &quot;Connection Timeout&quot;): result[&#x27;data&#x27;] = resp else: print resp tmpfile.write(resp) #这个将resp中的数据写入result.txt中，可以利用为将flag.txt中的数据放进result.txt中 tmpfile.close() result[&#x27;code&#x27;] = 200 if &quot;read&quot; in self.action: f = open(&quot;./%s/result.txt&quot; % self.sandbox, &#x27;r&#x27;) #打开方式为只读 result[&#x27;code&#x27;] = 200 result[&#x27;data&#x27;] = f.read() #读取result.txt中的数据 if result[&#x27;code&#x27;] == 500: result[&#x27;data&#x27;] = &quot;Action Error&quot; else: result[&#x27;code&#x27;] = 500 result[&#x27;msg&#x27;] = &quot;Sign Error&quot; return result def checkSign(self): if (getSign(self.action, self.param) == self.sign): return True else: return False @app.route(&quot;/geneSign&quot;, methods=[&#x27;GET&#x27;, &#x27;POST&#x27;])def geneSign(): param = urllib.unquote(request.args.get(&quot;param&quot;, &quot;&quot;)) action = &quot;scan&quot; return getSign(action, param) @app.route(&#x27;/De1ta&#x27;,methods=[&#x27;GET&#x27;,&#x27;POST&#x27;]) #注意这个绑定，接下来的几个函数都很重要，这个相当于c语言里面的主函数，接下来是调用其他函数的过程def challenge(): action = urllib.unquote(request.cookies.get(&quot;action&quot;)) #cookie传递action参数，对应不同的处理方式 param = urllib.unquote(request.args.get(&quot;param&quot;, &quot;&quot;)) #传递get方式的参数param sign = urllib.unquote(request.cookies.get(&quot;sign&quot;)) #cookie传递sign参数sign ip = request.remote_addr #获取请求端的ip地址 if(waf(param)): #调用waf函数进行过滤 return &quot;No Hacker!!!!&quot; task = Task(action, param, sign, ip) #创建Task类对象 return json.dumps(task.Exec()) #以json的形式返回到客户端 @app.route(&#x27;/&#x27;)def index(): return open(&quot;code.txt&quot;,&quot;r&quot;).read() def scan(param): socket.setdefaulttimeout(1) try: return urllib.urlopen(param).read()[:50] #这个可以利用为访问flag.txt。读取然后为下一步将flag.txt文件中的东西放到result.txt中做铺垫 except: return &quot;Connection Timeout&quot; def getSign(action, param): #getSign的作用是拼接secret_key,param,action，然后返回拼接后的字符串的md5加密值 return hashlib.md5(secert_key + param + action).hexdigest() def md5(content): #将传入的字符串进行md5加密 return hashlib.md5(content).hexdigest() def waf(param): #防火墙的作用是判断开头的几个字母是否是gopher 或者是file 如果是的话，返回true check=param.strip().lower() if check.startswith(&quot;gopher&quot;) or check.startswith(&quot;file&quot;): return True else: return Falseif __name__ == &#x27;__main__&#x27;: app.debug = False app.run(host=&#x27;0.0.0.0&#x27;,port=9999)
代码审计：首先绕过self.checkSign()，并且传入的action需要同时包含scan和read，然后if “scan” in self.action:执行将flag.txt中的数据写入result.txt中，继续if “read” in self.action:执行读取result.txt中的数据，并且放在 result[‘data’] 中 ， return json.dumps(task.Exec()) 接着返回以json的形式返回到客户端。 🔴构造payload的步骤：
首先需要绕过self.checkSign()分析一下相关源码，源码分别截取，方便分析
@app.route(&quot;/geneSign&quot;, methods=[&#x27;GET&#x27;, &#x27;POST&#x27;])def geneSign(): param = urllib.unquote(request.args.get(&quot;param&quot;, &quot;&quot;)) action = &quot;scan&quot; return getSign(action, param)def checkSign(self): if (getSign(self.action, self.param) == self.sign): return True else: return False def getSign(action, param): #getSign的作用是拼接secret_key,param,action，然后返回拼接后的字符串的md5加密值 return hashlib.md5(secert_key + param + action).hexdigest()
需要满足self.checkSign()， 就需要getSign(self.action, self.param) &#x3D;&#x3D; self.sign，（而sign值通过cookie传值） 就需要hashlib.md5(secert_key + param + action).hexdigest() &#x3D;&#x3D; self.sign， 说白了也就是hashlib.md5(secert_key + ‘flag.txt’ + ‘readscan’).hexdigest() &#x3D;&#x3D; self.sign，即我们需要得到 secert_key + ‘flag.txtreadscan’的哈希值 @app.route(&quot;/geneSign&quot;, methods=[&#x27;GET&#x27;, &#x27;POST&#x27;])def geneSign(): param = urllib.unquote(request.args.get(&quot;param&quot;, &quot;&quot;)) action = &quot;scan&quot; return getSign(action, param)
但是我们不知道secret_key的值是多少，它只存在于服务端，但是我们可以通过上面截取的源码中&#x2F;geneSign，来返回我们所需要的编码之后的哈希值 注意到&#x2F;geneSign中已经将action定为scan，所以我们传入的param可以为flag.txtread，这样的话还是会拼接为secert_key + ‘flag.txtreadscan’ payload1: /geneSign?param=flag.txtread
